func (l *Ledger) RegisterInstrument(id, name string, allowedError float64) error {
	id = strings.TrimSpace(id)
	name = strings.TrimSpace(name)
	if id == "" { return fmt.Errorf("%w: 器具编号不能留空", ErrInvalidInput) }
	if name == "" { return fmt.Errorf("%w: 器具名称不能留空", ErrInvalidInput) }
	if math.IsNaN(allowedError) || math.IsInf(allowedError, 0) {
		return fmt.Errorf("%w: 允许误差必须是有限数", ErrInvalidInput)
	}
	if allowedError < 0 {
		return fmt.Errorf("%w: 允许误差不能小于零", ErrInvalidInput)
	}
	for _, inst := range l.Instruments {
		if inst.ID == id {
			return fmt.Errorf("%w: 器具编号 %q 已存在", ErrConflict, id)
		}
	}
	l.Instruments = append(l.Instruments, Instrument{ID: id, Name: name, AllowedError: allowedError, Status: StatusPending})
	return l.save()
}
```

