func (l *Ledger) SetStatus(id string, status Status) error {
	id = strings.TrimSpace(id)
	if _, ok := parseStatus(string(status)); !ok {
		return fmt.Errorf("%w: 无效状态 %q", ErrInvalidInput, status)
	}
	for i := range l.Instruments {
		if l.Instruments[i].ID == id {
			l.Instruments[i].Status = status
			return l.save()
		}
	}
	return fmt.Errorf("%w: 器具 %q 不存在", ErrNotFound, id)
}
```

