func (l *Ledger) AddCertificate(c Certificate) (*Certificate, error) {
	c.Number = strings.TrimSpace(c.Number)
	c.InstrumentID = strings.TrimSpace(c.InstrumentID)
	c.Method = strings.TrimSpace(c.Method)
	c.Summary = strings.TrimSpace(c.Summary)

	if c.Number == "" { return nil, fmt.Errorf("%w: 证书编号不能留空", ErrInvalidInput) }
	if c.InstrumentID == "" { return nil, fmt.Errorf("%w: 器具编号不能留空", ErrInvalidInput) }
	if c.Method == "" { return nil, fmt.Errorf("%w: 校准方法不能留空", ErrInvalidInput) }
	if c.Summary == "" { return nil, fmt.Errorf("%w: 摘要不能留空", ErrInvalidInput) }
	if math.IsNaN(c.MeasuredError) || math.IsInf(c.MeasuredError, 0) {
		return nil, fmt.Errorf("%w: 测得误差必须是有限数", ErrInvalidInput)
	}
	cal, err := parseDate(c.CalDate)
	if err != nil { return nil, fmt.Errorf("%w: %v", ErrInvalidInput, err) }
	exp, err := parseDate(c.ExpiryDate)
	if err != nil { return nil, fmt.Errorf("%w: %v", ErrInvalidInput, err) }
	today := l.today()
	if cal.After(today) {
		return nil, fmt.Errorf("%w: 校准日期 %s 晚于本机今天 %s", ErrInvalidInput, c.CalDate, today.Format("2006-01-02"))
	}
	if !exp.After(cal) {
		return nil, fmt.Errorf("%w: 有效期截止日必须晚于校准日期", ErrInvalidInput)
	}
	inst := l.findInstrument(c.InstrumentID)
	if inst == nil {
		return nil, fmt.Errorf("%w: 器具 %q 不存在", ErrNotFound, c.InstrumentID)
	}
	// number uniqueness
	for i := range l.Certificates {
		existing := &l.Certificates[i]
		if existing.Number == c.Number {
			if sameCertificate(existing, &c) {
				return existing, nil
			}
			return nil, fmt.Errorf("%w: 证书编号 %q 已存在且内容不一致", ErrConflict, c.Number)
		}
	}
	// same instrument + same cal date
	for i := range l.Certificates {
		ex := &l.Certificates[i]
		if ex.InstrumentID == c.InstrumentID && ex.CalDate == c.CalDate {
			return nil, fmt.Errorf("%w: 器具 %s 在 %s 已有证书 %q，同一天不能接受两张不同证书", ErrConflict, c.InstrumentID, c.CalDate, ex.Number)
		}
	}
	l.Certificates = append(l.Certificates, c)
	if err := l.save(); err != nil { return nil, err }
	return &l.Certificates[len(l.Certificates)-1], nil
}
```

