func (l *Ledger) LatestCertificate(instrumentID string) *Certificate {
	var best *Certificate
	for i := range l.Certificates {
		c := &l.Certificates[i]
		if c.InstrumentID != instrumentID { continue }
		if best == nil || c.CalDate > best.CalDate {
			best = c
		}
	}
	return best
}
