func (l *Ledger) ApplyUse(id string) (bool, []string, error) {
	id = strings.TrimSpace(id)
	inst := l.findInstrument(id)
	if inst == nil {
		return false, nil, fmt.Errorf("%w: 器具 %q 不存在", ErrNotFound, id)
	}
	reasons, _ := l.evaluate(inst)
	rec := UsageRecord{
		InstrumentID: id,
		Time: l.now(),
		Approved: len(reasons) == 0,
		Reasons: reasons,
	}
	l.Usage = append(l.Usage, rec)
	if err := l.save(); err != nil { return false, nil, err }
	return rec.Approved, rec.Reasons, nil
}
