	Instrument Instrument
	Approved bool
	Reasons []string
	LatestCertificate *Certificate
	Certificates []Certificate
	UsageRecords []UsageRecord
}

func (l *Ledger) Check(id string) (*CheckResult, error) {
	id = strings.TrimSpace(id)
	inst := l.findInstrument(id)
	if inst == nil { return nil, fmt.Errorf(...) }
	reasons, latest := l.evaluate(inst)
	var certs []Certificate
	for _, c := range l.Certificates {
		if c.InstrumentID == id { certs = append(certs, c) }
	}
	sort.Slice(certs, func(i,j int) bool { return certs[i].CalDate < certs[j].CalDate })
	var recs []UsageRecord
	for _, u := range l.Usage {
		if u.InstrumentID == id { recs = append(recs, u) }
	}
	return &CheckResult{*inst, len(reasons)==0, reasons, latest, certs, recs}, nil
}
